-- Table: EMPLOYEE_MAIN
CREATE TABLE [EMPLOYEE_MAIN] (
    [EMP_SYSID] DECIMAL(38) NOT NULL  -- Employee System ID,
    [EMP_PIN_NO] DECIMAL(38) NOT NULL  -- PIN No,
    [EMP_APP_DATE] DATETIME2(3) NOT NULL  -- Application Date,
    [EMP_APP_UNIT] CHAR(3) NOT NULL  -- Applied Unit,
    [EMP_APP_GRADE] DECIMAL(38) NOT NULL  -- Applied Grade,
    [EMP_APP_POSITION] DECIMAL(38) NOT NULL  -- Applied Position,
    [EMP_APP_POSITIONDESC] VARCHAR(150) NOT NULL  -- Applied Position Description,
    [EMP_FRS_NAME] VARCHAR(65) NOT NULL  -- First Name,
    [EMP_MID_NAME] VARCHAR(65) NULL  -- Middle Name,
    [EMP_LST_NAME] VARCHAR(65) NULL  -- Last Name,
    [EMP_GENDER] CHAR(1) NOT NULL  -- M-Male ; F - Female,
    [EMP_DOB_RECORD] DATETIME2(3) NOT NULL  -- Date of Birth as per Records,
    [EMP_DOB_CELEBRATION] DATETIME2(3) NULL  -- Date of Birth for Celebration,
    [EMP_BLOOD_GROUP] DECIMAL(38) NULL  -- Blood Group,
    [EMP_NATIONALITY] DECIMAL(38) NULL  -- Nationality,
    [EMP_QUOTA] DECIMAL(38) NULL  -- Quota,
    [EMP_MARITAL_STATUS] DECIMAL(38) NULL  -- Married/Single/Divorcee,
    [EMP_RELIGION] DECIMAL(38) NULL  -- Religion,
    [EMP_PASSPORTNO] VARCHAR(65) NULL  -- Passport No,
    [EMP_PASSPORT_ISSDATE] DATETIME2(3) NULL  -- Passport Issue Date,
    [EMP_PASSPORT_PLACE] VARCHAR(65) NULL  -- Passport Place,
    [EMP_PASSPORT_EXPDATE] DATETIME2(3) NULL  -- Passport Expiry Date,
    [EMP_PAN_NO] VARCHAR(65) NULL  -- PAN No,
    [EMP_PAN_LOCATION] VARCHAR(65) NULL  -- PAN Location,
    [EMP_LASTOFFERDATE] DATETIME2(3) NULL  -- Offer Date,
    [EMP_OFFERNO] DECIMAL(38) NULL  -- Offer Letter No,
    [EMP_OFFERSTATUS] CHAR(1) NOT NULL  -- I - Incomplete ; O - Offer Letter Generated ; M - Modified ; A - Accepted ; R - Rejected,
    [EMP_OEMAIL_ID] VARCHAR(200) NULL  -- Official Email ID,
    [EMP_PEMAIL_ID] VARCHAR(200) NULL  -- Personal Email ID,
    [EMP_MOBILE_NO] VARCHAR(65) NULL  -- Mobile No,
    [EMP_TELNO] VARCHAR(50) NULL  -- Telephone No,
    [EMP_FAXNO] VARCHAR(50) NULL  -- Fax No,
    [EMP_EMERGENCYTEL] VARCHAR(50) NULL  -- Emergency Phone No,
    [EMP_CASUALPHOTOPATH] NVARCHAR(400) NULL  -- Employee Casual Photo,
    [EMP_FORMALPHOTOPATH] VARCHAR(200) NULL  -- Employee Formal Photo,
    [EMP_ANN_DATE] DATETIME2(3) NULL  -- Employee Anniversary Date,
    [EMP_LEAD_ROLE] CHAR(3) NOT NULL  -- BLT/CLT/GEN,
    [EMP_FTH_NAME] VARCHAR(65) NULL  -- Father/Husband's Name,
    [EMP_BIRTH_PLACE] VARCHAR(65) NULL  -- Birth Place,
    [EMP_LANG_SPEAK] VARCHAR(65) NULL  -- Languages - Known (Speak),
    [EMP_LANG_READ] VARCHAR(65) NULL  -- Languages - Known (Read),
    [EMP_LANG_WRITE] VARCHAR(65) NULL  -- Languages - Known (Write),
    [EMP_PEMAIL_ID2] VARCHAR(200) NULL  -- Personal Email ID 2,
    [EMP_APP_SALUTE] VARCHAR(10) NULL  -- Salute,
    [EMP_PROBDATE] DATETIME2(3) NULL  -- Prob. Review Date,
    [EMP_SOURCE_APP] CHAR(2) NULL  -- Source of applicaiton,
    [EMP_PROB_FLAG] CHAR(1) NULL  -- Probation flag,
    [EMP_PROSPECT_SYSID] DECIMAL(38) NULL  -- Prospect Sys id,
    [EMP_HANDICAPPED] CHAR(1) NULL  -- Handicapped (Y - Yes / N - No),
    [EMP_UPDATED_BY] DECIMAL(38) NULL  -- Last updated by,
    [EMP_UPDATED_ON] DATETIME2(3) NULL  -- Last updated on,
    [EMP_GOALDATE] DATETIME2(3) NULL,
    [EMP_CONFDATE] DATETIME2(3) NULL,
    [EMP_APPUNITID] DECIMAL(38) NOT NULL  -- Applied unit ID,
    [EMP_PREVEXPYEARS] DECIMAL(38) NULL  -- Previous Years of Experience,
    [EMP_CREATEDBY] DECIMAL(22,0) NULL,
    [EMP_CREATEDON] DATETIME2(3) NULL,
    [EMP_NOOFDEPEND] DECIMAL(38) NULL,
    [EMP_LASTCOMPANY] VARCHAR(50) NULL,
    [EMP_LASTCTCDRAWN] DECIMAL(22,0) NULL,
    [EMP_EDUCAMPUS] DECIMAL(22,0) NULL,
    [EMP_EDUSTREAM] DECIMAL(22,0) NULL,
    [EMP_VACANCYID] DECIMAL(22,0) NULL,
    [EMP_NATIONALITYID] DECIMAL(38) NULL,
    CONSTRAINT [PK_EMPLOYEE_MAIN] PRIMARY KEY ([EMP_SYSID])
);

